'use strict';
const fs = require('node:fs');
const path = require('node:path');
const { run } = require('node:test');
const ROOT = '/workspace/scratch/8f544d546bb7/panelreply-callback-receipts';
const { sourceEvidence, platformEvidence, collectNodeResults } = require(path.join(ROOT, 'scripts/test-evidence.cjs'));
const files = ['tests/callback-schedule-client.test.cjs', 'tests/platform-client-state.test.cjs', 'tests/callback-tasks.test.cjs',
  'tests/callback-tasks-api.test.cjs', 'tests/callback-task-parent-integrity.test.cjs'];
(async () => {
  const before = sourceEvidence(ROOT), platform = platformEvidence(), startedAt = new Date().toISOString(), events = [], log = [];
  for await (const event of run({ files: files.map(file => path.join(ROOT, file)), concurrency: 4 })) {
    if (['test:enqueue', 'test:start', 'test:pass', 'test:fail', 'test:summary'].includes(event.type)) events.push(event);
    if (['test:stdout', 'test:stderr', 'test:diagnostic'].includes(event.type)) log.push(String(event.data.message || ''));
    if (event.type === 'test:fail') log.push(String(event.data.details?.error?.stack || event.data.name));
  }
  const after = sourceEvidence(ROOT), results = collectNodeResults(events, ROOT, platform.platformKey);
  const sourceChanged = before.sourceTreeSha256 !== after.sourceTreeSha256 || before.sourceCommit !== after.sourceCommit;
  const evidence = { format: 'panelreply-node-evidence-v1', suite: 'callback-receipts-focused', ...before,
    startedAt, completedAt: new Date().toISOString(), sourceTreeSha256After: after.sourceTreeSha256, sourceChanged,
    platform, files, ...results, realProviderCalls: 0,
    scope: 'Dirty isolated development source. Focused Node client-state, SQLite store and in-process API regressions. No browser, native Safari, physical device, production or release acceptance claim.',
    creditedToPortfolioGoal: false };
  fs.writeFileSync('/tmp/panelreply-callback-receipts-after-node.json', JSON.stringify(evidence, null, 2) + '\n');
  fs.writeFileSync('/tmp/panelreply-callback-receipts-after-node.log', log.join('\n') + '\n');
  console.log(JSON.stringify({ sourceTreeSha256: before.sourceTreeSha256, sourceChanged, totals: results.totals,
    summarySuccess: results.summarySuccess, infrastructureErrors: results.infrastructureErrors }));
  if (!results.summarySuccess || sourceChanged) process.exitCode = 1;
})().catch(error => { console.error(error); process.exitCode = 1; });
